import re
import requests
from packaging.version import parse

ARTIFACTORY_API_TAF = "https://artifactory-espoo2.int.net.nokia.com/artifactory/api/storage/ute-taf-pypi-local/"
ARTIFACTORY_API_NAA = "https://artifactory-espoo1.ext.net.nokia.com/artifactory/api/storage/mn-android-apk/"


def warn_about_latest_uepc_libraries_version(logger, libs: dict):
    latest_is_dev_msg = "latest uploaded is development:"
    library_not_found_msg = "couldn't find library version"
    warning_msg = "Make sure you use latest versions our libraries on UEPC\n"
    for library in libs:
        name, def_version = library if isinstance(library, tuple) else (library, library_not_found_msg)
        try:
            package_name = requests.get(f"{ARTIFACTORY_API_TAF}{name}?lastModified", timeout=30).json().get("uri")
            version = package_name.split(name)[1].split("/")[1] if package_name else def_version
            if parse(libs[library]) < parse(version):
                version = version if "dev" not in version else f"{latest_is_dev_msg} {version}"
                warning_msg += f"\t{name}: {version}\n"
        except Exception:
            pass
    if any(library in warning_msg for library in libs):
        logger.warning(warning_msg)


def warn_about_latest_naa_version(logger, ue_naa_version: str):
    try:
        naa_packages = requests.get(ARTIFACTORY_API_NAA, timeout=30).json()
        naa_packages = [
            item["uri"]
            for item in naa_packages["children"]
            if not item["folder"] and "NokiaAndroidApplication" in item["uri"]
        ]
        parsed = []

        for filename in naa_packages:
            match = re.search(r'-(\d+-\d+-\d+)\.apk$', filename)
            if match:
                version_str = match.group(1)
                version_tuple = tuple(map(int, version_str.split('-')))
                parsed.append((version_tuple, filename))
        parsed.sort(reverse=True)

        latest_version_tuple, latest_filename = parsed[0]
        if tuple(map(int, ue_naa_version.split('.'))) < latest_version_tuple:
            latest_version_str = ".".join(map(str, latest_version_tuple))
            warning_msg = ("Make sure you use latest NAA version on your UE:\n"
                           f"\tcurrent NAA version: {ue_naa_version}\n"
                           f"\tlatest NAA version: {latest_version_str} ({latest_filename.lstrip('/').rstrip('.apk')})")
            logger.warning(warning_msg)

    except Exception as exc:
        logger.debug(f"Cannot verify if you use latest NAA version on your UE. Exception occurred: {str(exc)}")
